var asm = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.agents.ai/1.13.0/lib/net10.0/Microsoft.Agents.AI.dll");

var t = asm.GetType("Microsoft.Agents.AI.ChatClientAgent")!;
