foreach (var m in t.GetMethods(BindingFlags.Public|BindingFlags.Instance).Where(m => m.Name.Contains("Run")))
    Console.WriteLine($"  {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");

// Check AIAgent base
var baseT = t.BaseType!;
Console.WriteLine($"\nBase: {baseT.FullName}");
foreach (var m in baseT.GetMethods(BindingFlags.Public|BindingFlags.Instance|BindingFlags.DeclaredOnly).Where(m => m.Name.Contains("Run")))
    Console.WriteLine($"  {m.ReturnType} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");

// Check return type
var runMethod = t.GetMethods().First(m => m.Name == "RunAsync" && m.GetParameters().Length > 0 && m.GetParameters()[0].ParameterType == typeof(string));
Console.WriteLine($"\nRunAsync(string) returns: {runMethod.ReturnType}");
var retGenArgs = runMethod.ReturnType.GetGenericArguments();
if (retGenArgs.Length > 0)
{
    var agentResp = retGenArgs[0];
    Console.WriteLine($"  Inner type: {agentResp.FullName}");
    foreach (var p in agentResp.GetProperties(BindingFlags.Public|BindingFlags.Instance))
        Console.WriteLine($"    P: {p.PropertyType.Name} {p.Name}");
}
EOF
