 /// <summary>
 /// Provides web search and note-taking tools for the research agent.
 /// </summary>
 sealed class ResearchTools
 {
     private readonly HttpClient _httpClient = new();
     public List<NoteEntry> Notes { get; } = [];

     [Description("Search the web for information on a given query. Returns a list of search results with titles and snippets.")]
     public async Task<string> SearchWeb(
         [Description("The search query to look up")] string query)
     {
         Console.WriteLine($"  🔍 Searching: \"{query}\"");

         // Use a public search API (DuckDuckGo Instant Answer API)
         var encodedQuery = Uri.EscapeDataString(query);
         var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

         try
         {
             var response = await _httpClient.GetStringAsync(url);
             var doc = System.Text.Json.JsonDocument.Parse(response);
             var root = doc.RootElement;

             var results = new List<string>();

             // Get the abstract if available
             var abstractText = root.GetProperty("Abstract").GetString();
             var abstractSource = root.GetProperty("AbstractSource").GetString();
             if (!string.IsNullOrEmpty(abstractText))
             {
                 results.Add($"Source: {abstractSource}\n{abstractText}");
             }

             // Get related topics
             if (root.TryGetProperty("RelatedTopics", out var relatedTopics))
             {
                 foreach (var topic in relatedTopics.EnumerateArray().Take(5))
                 {
                     if (topic.TryGetProperty("Text", out var text))
                     {
                         var topicText = text.GetString();
                         if (!string.IsNullOrEmpty(topicText))
                         {
                             results.Add(topicText);
                         }
                     }
                 }
             }

             if (results.Count == 0)
             {
                 return $"No detailed results found for '{query}'. Try a more specific or different query.";
             }

             return $"Search results for '{query}':\n\n" + string.Join("\n\n---\n\n", results);
         }
         catch (Exception ex)
         {
             return $"Search failed for '{query}': {ex.Message}. Try a different query.";
         }
     }

     [Description("Take a note to record a key finding or insight during research. Use this to organize information before summarizing.")]
     public string TakeNote(
         [Description("The category or topic area for this note")] string category,
         [Description("The content of the note - a key finding or insight")] string content)
     {
         Console.WriteLine($"  📝 Note [{category}]: {content[..Math.Min(content.Length, 80)]}...");
         Notes.Add(new NoteEntry(category, content));
         return $"Note recorded under '{category}'. Total notes: {Notes.Count}";
     }

     [Description("Retrieve all notes taken so far during the research session.")]
     public string GetNotes()
     {
         if (Notes.Count == 0)
         {
             return "No notes have been taken yet.";
         }

         var grouped = Notes.GroupBy(n => n.Category);
         var output = "Current research notes:\n\n";
         foreach (var group in grouped)
         {
             output += $"## {group.Key}\n";
             foreach (var note in group)
             {
                 output += $"- {note.Content}\n";
             }
             output += "\n";
         }
         return output;
     }
 }

 record NoteEntry(string Category, string Content);
